def even_Power_Sum(n):
    """Write a python function to find the sum of fifth power of first n even natural numbers."""
    if n <= 0:
        return 0
    # sum_{i=1}^{n} (2*i)**5 == 32 * sum_{i=1}^{n} i**5, using the
    # closed form sum_{i=1}^{n} i**5 == n**2 * (n+1)**2 * (2*n**2 + 2*n - 1) / 12.
    return 32 * (n**2 * (n + 1) ** 2 * (2 * n**2 + 2 * n - 1) // 12)
